#include <stdlib.h>
#include <string.h>

#define RADIX 255
#define OFF1 5
#define OFF2 2
#define LITSIZE 4

int cc[1000000];
unsigned char output[1000000];
int output_len = 0;
long low = 0;
long range = 1;

void normalize() {
    while (range < RADIX) {
        int byte_val = (low / RADIX) + 1;
