        range *= RADIX;
    }
}

void put_bit(int bit, int ctx) {
    normalize();
    int *counts = cc + ctx * 2;
    long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);
    if (bit) {
        low += split;
        range -= split;
        counts[1]++;
    } else {
        range = split;
        counts[0]++;
    }
}

void put_integer(int value, int tmp, int ctx) {
    ctx *= 99;
    value += (1 << tmp);

    int bit_len = 0;
    int test = value;
    while (test > 1) {
        test >>= 1;
        bit_len++;
    }

    for (int i = 0; i < bit_len; i++) {
        put_bit(0, tmp + 1 + ctx);
        tmp++;
    }
    put_bit(1, tmp + 1 + ctx);

    for (int i = bit_len - 1; i >= 0; i--) {
        put_bit((value >> i) & 1, ctx);
    }
