#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define RADIX 255
#define OFF1 5
#define OFF2 2
#define LITSIZE 4

int cc[1000000];
unsigned char output[1000000];
int output_len = 0;
long low = 0;
long range = 1;

void normalize() {
    while (range < RADIX) {
        int byte_val = (low / RADIX) + 1;
        if (byte_val > 255) byte_val = 255;
        output[output_len++] = byte_val;

        // Correct formula to maintain synchronization with decoder
        low = (low / RADIX) * (RADIX * RADIX + 1) + (low % RADIX) * RADIX;
        range *= RADIX;
    }
}

void put_bit(int bit, int ctx) {
    normalize();
    int *counts = cc + ctx * 2;
    long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);
    if (bit) {
        low += split;
        range -= split;
        counts[1]++;
    } else {
        range = split;
        counts[0]++;
    }
}

void put_integer(int value, int tmp, int ctx) {
    ctx *= 99;
    value += (1 << tmp);

    int bit_len = 0;
    int test = value;
    while (test > 1) {
        test >>= 1;
        bit_len++;
    }

    for (int i = 0; i < bit_len; i++) {
        put_bit(0, tmp + 1 + ctx);
        tmp++;
    }
    put_bit(1, tmp + 1 + ctx);

    for (int i = bit_len - 1; i >= 0; i--) {
        put_bit((value >> i) & 1, ctx);
    }
}

void flush() {
    for (int i = 0; i < 10; i++) {
